#!/usr/bin/env python3
"""Offline review of the one captured official structured birth record for NAS Anderson."""
from pathlib import Path
import copy,gzip,hashlib,json
ROOT=Path(__file__).resolve().parents[2];B=Path(__file__).resolve().parent
master=ROOT/'uk_birthplace_checkout/studies/scientist_birthplace_completion_v4/outputs/birthplace_rows.jsonl.gz'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(master)=='abbce4e99ad51252dd5e127a0609bc6c4950c121afa2dd126bfc2187b39cd4e8'
with gzip.open(master,'rt') as f:rows=[json.loads(x) for x in f if x.strip()]
nas=next(r for r in rows if r['cohort']=='NAS' and r['record_id']=='https://www.nasonline.org/directory-entry/carl-d-anderson-qydvwd/')
nobel=next(r for r in rows if r['cohort']=='Nobel_science' and r['record_id']=='43')
meta=json.loads((B/'anderson_corroboration_capture.json').read_text());response=B/'nobel_physics_corroboration_response.bin'
assert meta['status']==200 and meta['parse_status']=='valid_official_API_JSON' and meta['retries']==0
assert sha(response)==meta['response_sha256']==nobel['birthplace_source_sha256']
source=json.loads(response.read_bytes());objs=[x for x in source['laureates'] if x.get('id')=='43'];assert len(objs)==1;s=objs[0]
assert s['fullName']['en']=='Carl David Anderson'==nas['v4_birthplace_fact_evidence']['source_subject_heading']
assert s['knownName']['en']==nas['name']=='Carl D. Anderson'
assert s['birth']['date']==nas['dob']=='1905-09-03'
prize=[p for p in s['nobelPrizes'] if p['awardYear']=='1936' and p['category']['en']=='Physics'];assert len(prize)==1
assert prize[0]['motivation']['en']=='for his discovery of the positron'
context=ROOT/'academy_v4_workers/vol73/raw/chapter_03.txt';t=context.read_text();assert 'In 1936, when he was awarded the Nobel Prize' in t and 'discovery of the positron' in t
place=s['birth']['place'];assert place['city']['en']=='New York, NY' and place['locationString']['en']=='New York, NY, USA'
identity={'result':'pass_independent_same_person_source_check_for_birthplace_qualification_only','expanded_name_exact_match':'Carl David Anderson','known_name_exact_match':'Carl D. Anderson','official_source_birth_date':s['birth']['date'],'official_source_birth_date_used_for':'identity consistency check only; not adopted as native Nobel DOB and no native NAS DOB edit','NAS_native_DOB_exact_match':True,'Nobel_prize_context':{'category':'Physics','award_year':'1936','motivation':prize[0]['motivation']['en']},'NAS_saved_memoir_prize_context_matches':True,'NAS_saved_memoir_original_SHA':nas['birthplace_source_sha256'],'NAS_saved_memoir_context_text_file':str(context.relative_to(ROOT)),'NAS_saved_memoir_context_text_SHA':sha(context),'unique_official_id43_objects_in_response':len(objs),'unique_same_full_name_and_source_DOB_objects_in_response':sum(x.get('fullName',{}).get('en')=='Carl David Anderson' and x.get('birth',{}).get('date')=='1905-09-03' for x in source['laureates']),'person_QIDs_used_or_assigned':False,'statistical_cross_cohort_deduplication':False,'independent_read_only_second_agent_review':'concurred: expanded name, exact source DOB, Physics1936 and positron anchors support new official source qualification'}
assert identity['unique_same_full_name_and_source_DOB_objects_in_response']==1
f={'cohort':'NAS','record_id':nas['record_id'],'name':nas['name'],'native_dob':nas['dob'],'raw_birthplace':place['locationString']['en'],'source_grade':'S1','source_type':'official_Nobel_Prize_API_structured_birth_place','source_grade_basis':'direct structured birth.place fields from official Nobel API; separate from prior signed NAS memoir S2','source_url':meta['request_url'],'source_urls':[meta['request_url']],'source_title':'Official Nobel Prize API 2.1 physics laureate collection; id43 Carl David Anderson','source_subject_heading':s['fullName']['en'],'source_sha256':sha(response),'original_bytes_sha256':sha(response),'original_bytes_length':response.stat().st_size,'capture_kind':'original_HTTP_response_bytes','capture_scope':'complete original physics collection API JSON response; only id43 used for this fact','source_capture_kind':'original_HTTP_JSON_bytes','source_capture_file':str(response.relative_to(ROOT)),'capture_metadata_file':'academy_v5_workers/geography/anderson_corroboration_capture.json','retrieved_utc':meta['captured_at_utc'],'evidence_quote':place['locationString']['en'],'evidence_quote_word_count':len(place['locationString']['en'].split()),'evidence_kind':'structured_birth_place_field; exact field string, not prose born quotation','evidence_locator':{'object':'laureates[id=43]','field':'birth.place.locationString.en','also_checked_field':'birth.place.city.en'},'source_fields':{'id':'43','fullName.en':s['fullName']['en'],'knownName.en':s['knownName']['en'],'birth.date':s['birth']['date'],'birth.place.city.en':place['city']['en'],'birth.place.country.en':place['country']['en'],'birth.place.locationString.en':place['locationString']['en'],'nobelPrizes[0].category.en':prize[0]['category']['en'],'nobelPrizes[0].awardYear':prize[0]['awardYear'],'nobelPrizes[0].motivation.en':prize[0]['motivation']['en']},'identity_review':identity,'identity_independent_QA_passed':True,'frozen_baseline_row':copy.deepcopy(nas),'baseline_sha256':sha(master),'prior_v4_raw_birthplace':nas['raw_birthplace'],'prior_v4_S2_overlay_to_preserve_completely':{'v4_birthplace_fact_evidence':copy.deepcopy(nas['v4_birthplace_fact_evidence']),'v4_geographic_review':copy.deepcopy(nas['v4_geographic_review']),'v4_geography_before_overlay':copy.deepcopy(nas['v4_geography_before_overlay'])},'qualification_relation':'new official S1 source supplies explicit NY state qualifier for prior NAS S2 New York City; prior exact-name query hotel uncertainty remains in v4 audit','prior_query_not_retried':True,'source_birthplace_grain':'literal official structured city/state/country wording; no point or unique place entity assigned','native_fields_modified':False,'Nobel_cohort_row_modified':False,'Nobel_native_DOB_still_blank':nobel['dob']=='','country_assigned':False,'birthpoint_coordinates_assigned':False,'unique_place_entity_assigned':False,'person_QID_assigned_or_modified':False,'statistical_cross_cohort_deduplication':False,'geography_assignment_performed':False,'root_QA_and_geography_pending':True}
assert f['evidence_quote_word_count']<=25
(B/'anderson_geographic_qualification_fact.jsonl').write_text(json.dumps(f,sort_keys=True,ensure_ascii=False)+'\n')
print('anderson_fact_sha256',sha(B/'anderson_geographic_qualification_fact.jsonl'))
